import unittest,re
from tools.kjv_archive import load_register,read
class GalatiansSharedLifeTests(unittest.TestCase):
 def test_shared_life_faith_promise(self):
  prior,_=load_register('0.10-kjv.246');lang,manifest=load_register('0.10-kjv.247')
